<h2>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'مقدمة' : __('مقدمة') }}</h2>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'تهدف شركة اودير («اودير») إلى تزويدك بمنصة سهلة الاستخدام لمجموعة متنوعة من خدمات الموارد البشرية والخدمات التشغيلية. وبذلك، فإننا ندرك أنك، سواء كنت شركة تقدم بياناتها («العميل»)، أو أحد موظفيها أو المتعاقدين معها أو المتعاقدين من الباطن معها («المستخدمون المصرح لهم»)، أو مجرد فرد يزور موقعنا الإلكتروني («الزوار») — ويُشار إليكم جميعًا بـ«أنت» أو «الخاص بك» — تأتمننا على بياناتك الشخصية. والحفاظ على هذه الثقة هو أولويتنا القصوى، ولذلك نلتزم بالمبادئ الواردة في سياسة الخصوصية هذه.' : __('تهدف شركة اودير («اودير») إلى تزويدك بمنصة سهلة الاستخدام لمجموعة متنوعة من خدمات الموارد البشرية والخدمات التشغيلية. وبذلك، فإننا ندرك أنك، سواء كنت شركة تقدم بياناتها («العميل»)، أو أحد موظفيها أو المتعاقدين معها أو المتعاقدين من الباطن معها («المستخدمون المصرح لهم»)، أو مجرد فرد يزور موقعنا الإلكتروني («الزوار») — ويُشار إليكم جميعًا بـ«أنت» أو «الخاص بك» — تأتمننا على بياناتك الشخصية. والحفاظ على هذه الثقة هو أولويتنا القصوى، ولذلك نلتزم بالمبادئ الواردة في سياسة الخصوصية هذه.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'نبذل قصارى جهدنا لحماية معلوماتك الشخصية فيما يتعلق باستخدام موقعنا وخدماتنا. ولتحقيق ذلك، نسعى إلى تطبيق ضمانات أمنية إدارية وتقنية ومادية مناسبة لحماية المعلومات التي تتم معالجتها من خلال المنصة.' : __('نبذل قصارى جهدنا لحماية معلوماتك الشخصية فيما يتعلق باستخدام موقعنا وخدماتنا. ولتحقيق ذلك، نسعى إلى تطبيق ضمانات أمنية إدارية وتقنية ومادية مناسبة لحماية المعلومات التي تتم معالجتها من خلال المنصة.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'في اودير، نلتزم بحماية بياناتك الشخصية واحترام خصوصيتك. وعند استخدامك لخدماتنا، قد تشارك بعض المعلومات معنا. وسنبذل قصارى جهدنا لإطلاعك على المعلومات التي نجمعها وأسباب جمعها وكيفية استخدامها بموجب سياسة الخصوصية هذه.' : __('في اودير، نلتزم بحماية بياناتك الشخصية واحترام خصوصيتك. وعند استخدامك لخدماتنا، قد تشارك بعض المعلومات معنا. وسنبذل قصارى جهدنا لإطلاعك على المعلومات التي نجمعها وأسباب جمعها وكيفية استخدامها بموجب سياسة الخصوصية هذه.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'تنطبق سياسة الخصوصية هذه على البيانات المقدمة على موقع اودير الإلكتروني أو من خلاله، وعلى منصة اودير لإدارة الموارد البشرية، وجميع الخدمات الأخرى التي تقدمها اودير من خلال الموقع والمنصة، ويُشار إليها مجتمعةً باسم «الخدمات».' : __('تنطبق سياسة الخصوصية هذه على البيانات المقدمة على موقع اودير الإلكتروني أو من خلاله، وعلى منصة اودير لإدارة الموارد البشرية، وجميع الخدمات الأخرى التي تقدمها اودير من خلال الموقع والمنصة، ويُشار إليها مجتمعةً باسم «الخدمات».') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'تصف سياسة الخصوصية هذه ممارسات اودير المتعلقة بالخصوصية فيما يخص استخدام الموقع والمنصة والخدمات. كما توضح الخيارات المتاحة لك فيما يتعلق باستخدام معلوماتك الشخصية وكيفية طلب الوصول إليها أو تحديثها أو حذفها، وفقًا للقوانين المعمول بها.' : __('تصف سياسة الخصوصية هذه ممارسات اودير المتعلقة بالخصوصية فيما يخص استخدام الموقع والمنصة والخدمات. كما توضح الخيارات المتاحة لك فيما يتعلق باستخدام معلوماتك الشخصية وكيفية طلب الوصول إليها أو تحديثها أو حذفها، وفقًا للقوانين المعمول بها.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'يقتصر استخدام المعلومات التي يتم جمعها من خلال الخدمات أو من أجلها على الأغراض المرتبطة بتقديم الخدمات التي استعان العميل والمستخدمون المصرح لهم باودير من أجلها، وغيرها من الأغراض الموضحة في سياسة الخصوصية هذه.' : __('يقتصر استخدام المعلومات التي يتم جمعها من خلال الخدمات أو من أجلها على الأغراض المرتبطة بتقديم الخدمات التي استعان العميل والمستخدمون المصرح لهم باودير من أجلها، وغيرها من الأغراض الموضحة في سياسة الخصوصية هذه.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'باستخدامك للخدمات، فإنك تقر باطلاعك على سياسة الخصوصية هذه. وتتم معالجة بياناتك ومعلوماتك وفقًا لشروط استخدام المنصة والقوانين المعمول بها. ولا يُعد استخدام الخدمات وحده موافقةً على أي معالجة تتطلب موافقة مستقلة بموجب القانون.' : __('باستخدامك للخدمات، فإنك تقر باطلاعك على سياسة الخصوصية هذه. وتتم معالجة بياناتك ومعلوماتك وفقًا لشروط استخدام المنصة والقوانين المعمول بها. ولا يُعد استخدام الخدمات وحده موافقةً على أي معالجة تتطلب موافقة مستقلة بموجب القانون.') }}</p>

<h2>{{ \App\Http\Middleware\SetLocale::isRtl() ? '1. ما المعلومات التي نجمعها؟' : __('1. ما المعلومات التي نجمعها؟') }}</h2>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'تبعًا لنوع الخدمات التي تستخدمها داخل منصة اودير، قد يُطلب منك تقديم مجموعة متنوعة من المعلومات الشخصية أو معلومات الشركة أو المعلومات المتعلقة بالموظفين. وقد تشمل هذه المعلومات الفئات التالية:' : __('تبعًا لنوع الخدمات التي تستخدمها داخل منصة اودير، قد يُطلب منك تقديم مجموعة متنوعة من المعلومات الشخصية أو معلومات الشركة أو المعلومات المتعلقة بالموظفين. وقد تشمل هذه المعلومات الفئات التالية:') }}</p>

<h3>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'معلومات التسجيل' : __('معلومات التسجيل') }}</h3>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'تشير معلومات التسجيل إلى بيانات حسابك، مثل اسم المستخدم والبريد الإلكتروني وكلمات المرور أو بيانات المصادقة اللازمة لتسجيل الدخول، إلى جانب أي معلومات أخرى ضرورية لإنشاء حسابك أو تحديثه أو إدارته.' : __('تشير معلومات التسجيل إلى بيانات حسابك، مثل اسم المستخدم والبريد الإلكتروني وكلمات المرور أو بيانات المصادقة اللازمة لتسجيل الدخول، إلى جانب أي معلومات أخرى ضرورية لإنشاء حسابك أو تحديثه أو إدارته.') }}</p>

<h3>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'المعلومات الشخصية' : __('المعلومات الشخصية') }}</h3>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'قد تشمل المعلومات الشخصية الاسم الكامل، والعنوان، ورقم الهاتف، والبريد الإلكتروني، وتاريخ الميلاد، والجنسية، والرقم القومي أو غيره من أرقام الهوية، والرقم التأميني، وغيرها من البيانات اللازمة لتقديم خدمات الموارد البشرية، بحسب الوظائف التي يستخدمها العميل.' : __('قد تشمل المعلومات الشخصية الاسم الكامل، والعنوان، ورقم الهاتف، والبريد الإلكتروني، وتاريخ الميلاد، والجنسية، والرقم القومي أو غيره من أرقام الهوية، والرقم التأميني، وغيرها من البيانات اللازمة لتقديم خدمات الموارد البشرية، بحسب الوظائف التي يستخدمها العميل.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'وقد تشمل هذه المعلومات أيضًا بيانات الموظفين التي يدخلها العميل إلى المنصة، وفقًا لطبيعة استخدامه للخدمات.' : __('وقد تشمل هذه المعلومات أيضًا بيانات الموظفين التي يدخلها العميل إلى المنصة، وفقًا لطبيعة استخدامه للخدمات.') }}</p>

<h3>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'معلومات الشركة' : __('معلومات الشركة') }}</h3>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'قد تشمل معلومات الشركة اسم الشركة، وبيانات الاتصال، والعنوان، ورقم السجل التجاري، وأرقام التسجيل الضريبي، وبيانات التأمينات الاجتماعية، ومعلومات مسؤولي الشركة، وغيرها من البيانات اللازمة لإنشاء حساب الشركة وإدارة اشتراكها وتقديم الخدمات لها.' : __('قد تشمل معلومات الشركة اسم الشركة، وبيانات الاتصال، والعنوان، ورقم السجل التجاري، وأرقام التسجيل الضريبي، وبيانات التأمينات الاجتماعية، ومعلومات مسؤولي الشركة، وغيرها من البيانات اللازمة لإنشاء حساب الشركة وإدارة اشتراكها وتقديم الخدمات لها.') }}</p>

<h3>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'المعلومات الديموغرافية' : __('المعلومات الديموغرافية') }}</h3>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'قد تشمل المعلومات الديموغرافية بيانات مثل العمر والجنسية والحالة الاجتماعية والمؤهل الدراسي والجنس ومكان العمل، متى كانت هذه البيانات مطلوبة لأغراض الموارد البشرية وأدخلها العميل إلى المنصة.' : __('قد تشمل المعلومات الديموغرافية بيانات مثل العمر والجنسية والحالة الاجتماعية والمؤهل الدراسي والجنس ومكان العمل، متى كانت هذه البيانات مطلوبة لأغراض الموارد البشرية وأدخلها العميل إلى المنصة.') }}</p>

<h3>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'معلومات المزايا والتأمينات' : __('معلومات المزايا والتأمينات') }}</h3>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'إذا اختار العميل استخدام المنصة لإدارة بيانات التأمينات الاجتماعية أو المزايا أو الاستحقاقات المرتبطة بالموظفين، فقد تتم معالجة هذه البيانات من خلال المعلومات التي يدخلها العميل أو يرفعها إلى المنصة.' : __('إذا اختار العميل استخدام المنصة لإدارة بيانات التأمينات الاجتماعية أو المزايا أو الاستحقاقات المرتبطة بالموظفين، فقد تتم معالجة هذه البيانات من خلال المعلومات التي يدخلها العميل أو يرفعها إلى المنصة.') }}</p>

<p>{{ \App\Http\Middleware\SetLocale::isRtl() ? 'وقد تشمل هذه البيانات أرقام التأمينات الاجتماعية، والبيانات المرتبطة بالاستحقاقات والمزايا، وغيرها من المعلومات اللازمة لتقديم الخدمات ذات الصلة.' : __('وقد تشمل هذه البيانات أرقام التأمينات الاجتماعية، والبيانات المرتبطة بالاستحقاقات والمزايا، وغيرها من المعلومات اللازمة لتقديم الخدمات ذات الصلة.') }}</p>

